import 'dart:convert';
import 'dart:async';

class OpenAIServiceLocal {
  static const String apiKey = 'sk-your-api-key-here';
  
  // Respuestas simuladas para nutrición sin dependencias externas
  static const Map<String, String> nutritionResponses = {
    'recomendacion': 'Como experto en nutrición, te recomiendo mantener una dieta balanceada con proteínas, carbohidratos y grasas saludables. Aumenta el consumo de frutas y verduras.',
    'alimento': 'El análisis nutricional incluye: calorías moderadas, proteínas esenciales, fibra dietética, vitaminas y minerales. Consumir con moderación.',
    'plan': 'Desayuno: frutas frescas y avena. Almuerzo: proteína magra con verduras. Cena: salmón con ensalada. Meriendas: frutos secos.',
  };

  /// Valida que el mensaje no esté vacío
  bool _validateMessage(String message) {
    if (message.isEmpty) {
      throw Exception('El mensaje no puede estar vacío');
    }
    return true;
  }

  /// Simula respuesta de IA para nutrición
  String _generateResponse(String message) {
    final lowerMessage = message.toLowerCase();
    
    if (lowerMessage.contains('recomend') || lowerMessage.contains('nutrici')) {
      return nutritionResponses['recomendacion']!;
    } else if (lowerMessage.contains('aliment') || lowerMessage.contains('compos')) {
      return nutritionResponses['alimento']!;
    } else if (lowerMessage.contains('plan') || lowerMessage.contains('dieta')) {
      return nutritionResponses['plan']!;
    } else {
      return 'Proporciona información sobre nutrición y alimentación saludable basada en tus necesidades.';
    }
  }

  /// Obtiene recomendaciones de nutrición
  Future<String> getNutritionRecommendation(String userInput) async {
    try {
      _validateMessage(userInput);
      await Future.delayed(Duration(milliseconds: 500)); // Simula latencia
      return _generateResponse('recomendacion: $userInput');
    } catch (e) {
      throw Exception('Error al obtener recomendación: $e');
    }
  }

  /// Analiza composición de un alimento
  Future<String> analyzeFoodComposition(String foodName) async {
    try {
      _validateMessage(foodName);
      await Future.delayed(Duration(milliseconds: 500));
      return _generateResponse('alimento: $foodName');
    } catch (e) {
      throw Exception('Error al analizar alimento: $e');
    }
  }

  /// Genera plan dietético personalizado
  Future<String> generateDietPlan(String preferences) async {
    try {
      _validateMessage(preferences);
      await Future.delayed(Duration(milliseconds: 500));
      return _generateResponse('plan: $preferences');
    } catch (e) {
      throw Exception('Error al generar plan: $e');
    }
  }

  /// Verifica estabilidad del servicio
  Future<bool> healthCheck() async {
    try {
      await Future.delayed(Duration(milliseconds: 200));
      return true;
    } catch (e) {
      return false;
    }
  }
}

